#include <stdio.h>

struct student
{
    char name[20];
    int c, m, e;
};

int main()
{
    struct student s[50];
    int n, i, best = 0, sum, bs = -1;
    scanf("%d", &n);
    for (i = 0; i < n; i++)
        scanf("%s %d %d %d", s[i].name, &s[i].c, &s[i].m, &s[i].e);
    for (i = 0; i < n; i++)
    {
        sum = s[i].c + s[i].m + s[i].e;
        if (sum > bs)
        {
            bs = sum;
            best = i;
        }
    }
    printf("%s\n", s[best].name);
    return 0;
}

#include <stdio.h>

struct student
{
    char name[20];
    int c, m, e;
    int sum;
};

int main()
{
    struct student s[50], t;
    int n, i, j;
    scanf("%d", &n);
    for (i = 0; i < n; i++)
    {
        scanf("%s %d %d %d", s[i].name, &s[i].c, &s[i].m, &s[i].e);
        s[i].sum = s[i].c + s[i].m + s[i].e;
    }
    for (i = 0; i < n - 1; i++)
        for (j = 0; j < n - 1 - i; j++)
            if (s[j].sum < s[j + 1].sum)
            {
                t = s[j];
                s[j] = s[j + 1];
                s[j + 1] = t;
            }
    for (i = 0; i < n; i++)
        printf("%s %d\n", s[i].name, s[i].sum);
    return 0;
}

#include <stdio.h>

struct date
{
    int y, m, d;
};

int daysOfMonth(int y, int m)
{
    int t[13] = {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    if (m == 2 && ((y % 4 == 0 && y % 100 != 0) || y % 400 == 0))
        return 29;
    return t[m];
}

int main()
{
    struct date a;
    scanf("%d %d %d", &a.y, &a.m, &a.d);
    if (a.d < daysOfMonth(a.y, a.m))
        a.d = a.d + 1;
    else
    {
        a.d = 1;
        if (a.m < 12)
            a.m = a.m + 1;
        else
        {
            a.m = 1;
            a.y = a.y + 1;
        }
    }
    printf("%d %d %d\n", a.y, a.m, a.d);
    return 0;
}

